# Dedup: keep LAST occurrence for each well (second batch has more detailed notes)
seen = {}
for r in RAW:
    seen[r["well"]] = r
data = list(seen.values())

n_total = len(data)
n_concordant = sum(1 for r in data if r["concordant"])
overall_pct = round(100.0 * n_concordant / n_total, 2)

# by_class
classes = {}
for r in data:
    cls = r["classification"]
    if cls not in classes:
        classes[cls] = {"n": 0, "concordant": 0, "eds": []}
    classes[cls]["n"] += 1
    if r["concordant"]:
        classes[cls]["concordant"] += 1
    classes[cls]["eds"].append(r["ed_mame_medaka"])

by_class = []
for cls in sorted(classes.keys()):
    c = classes[cls]
    pct = round(100.0 * c["concordant"] / c["n"], 2)
    eds_sorted = sorted(c["eds"])
    n_eds = len(eds_sorted)
    mid = n_eds // 2
    if n_eds % 2 == 1:
        med_ed = float(eds_sorted[mid])
    else:
        med_ed = (eds_sorted[mid - 1] + eds_sorted[mid]) / 2.0
    by_class.append({
        "cls": cls,
        "n": c["n"],
        "concordant": c["concordant"],
        "pct": pct,
        "median_ed": med_ed
    })

# divergent wells: ed_mame_medaka > 2
divergent = []
for r in data:
    if r["ed_mame_medaka"] > 2:
        divergent.append(r)

# print results
import json as _json
print("=== DEDUP STATS ===")
print(f"Total wells (after dedup): {n_total}")
print(f"Concordant: {n_concordant}")
print(f"Overall concordance: {overall_pct}%")
print()
print("=== BY CLASS ===")
for c in by_class:
    print(c)
print()
print("=== DIVERGENT WELLS (ed > 2) ===")
for r in divergent:
    print(f"  {r['well']}: ed={r['ed_mame_medaka']}, cls={r['classification']}, concordant={r['concordant']}, note={r['note']}")
